export default async function subscribe({ event, baseId, tableId }, ctx) {
  const { email, topic, frequency } = event.event ?? {};
  if (
    typeof email !== "string" ||
    !email.includes("@") ||
    typeof topic !== "string" ||
    !topic.trim() ||
    !["daily", "weekly", "surprise me"].includes(frequency)
  )
    throw Error("Invalid subscription");
  const pending = await ctx.state.get("factoid-pending");
  if (pending) throw Error("Inspect unresolved " + pending.stage);
  let offset,
    records = [];
  do {
    const r = await ctx.actions.call("airtable.list_records", {
      baseId,
      tableIdOrName: tableId,
      filterByFormula: "{Email} = '" + email.replace(/\\/g, "\\\\").replace(/'/g, "\\'") + "'",
      ...(offset ? { offset } : {}),
    });
    records.push(...r.records);
    offset = r.offset;
  } while (offset);
  if (records.length > 1) throw Error("Multiple subscribers use this email");
  const fields = {
    Email: email,
    Topic: topic,
    Status: "active",
    Interval: frequency === "surprise me" ? "surprise" : frequency,
    "Start Day": new Intl.DateTimeFormat("en-US", { weekday: "short", timeZone: "UTC" }).format(
      new Date(),
    ),
  };
  await ctx.state.set("factoid-pending", { stage: "save subscription", email });
  const saved = records.length
    ? await ctx.actions.call("airtable.update_records", {
        baseId,
        tableIdOrName: tableId,
        records: [{ id: records[0].id, fields }],
      })
    : await ctx.actions.call("airtable.create_records", {
        baseId,
        tableIdOrName: tableId,
        records: [{ fields }],
      });
  if (saved.records.length !== 1 || !saved.records[0].id) throw Error("Subscription unconfirmed");
  await ctx.state.set("factoid-pending", {
    stage: "send subscription confirmation",
    email,
    id: saved.records[0].id,
  });
  const m = await ctx.actions.call("gmail.send_email", {
    to: email,
    subject: "Learn something every day confirmation",
    body: "This confirms your subscription.\n\nTopic: " + topic + "\nSchedule: " + frequency,
  });
  if (!m.messageId) throw Error("Confirmation unconfirmed");
  await ctx.state.set("factoid-pending", null);
  return { status: "subscribed" };
}

