export default async function unsubscribe({ event, baseId, tableId }, ctx) {
  event = event.event ?? {};
  if (typeof event.ID !== "string" || !event.ID.trim()) throw Error("Subscriber ID required");
  const pending = await ctx.state.get("factoid-pending");
  if (pending) throw Error("Inspect unresolved " + pending.stage);
  await ctx.state.set("factoid-pending", { stage: "deactivate subscription", id: event.ID });
  const r = await ctx.actions.call("airtable.update_records", {
    baseId,
    tableIdOrName: tableId,
    records: [{ id: event.ID, fields: { Status: "inactive" } }],
  });
  if (r.records.length !== 1 || r.records[0].id !== event.ID)
    throw Error("Unsubscribe unconfirmed");
  await ctx.state.set("factoid-pending", null);
  return { status: "unsubscribed" };
}

