export default async function list({ baseId, tableId }, ctx) {
  const pending = await ctx.state.get("factoid-pending");
  if (pending) throw Error("Inspect unresolved " + pending.stage);
  let offset,
    records = [];
  do {
    const r = await ctx.actions.call("airtable.list_records", {
      baseId,
      tableIdOrName: tableId,
      filterByFormula: "{Status} = 'active'",
      ...(offset ? { offset } : {}),
    });
    records.push(...r.records);
    offset = r.offset;
  } while (offset);
  return { records };
}

