export default async function next({ records, previous }, ctx) {
  let i = previous?.index ?? 0;
  const now = Date.now();
  while (i < records.length) {
    const r = records[i++],
      f = r.fields || {},
      last = f["Last Sent"] ? Date.parse(f["Last Sent"]) : 0;
    if (!f.Email || !f.Topic) throw Error("Subscription missing email or topic");
    if (f.Interval === "weekly" && last && now - last < 604800000) continue;
    if (f.Interval === "surprise" && Math.floor(Math.random() * 10) !== 7) continue;
    if (!["daily", "weekly", "surprise"].includes(f.Interval)) continue;
    const history = (await ctx.state.get("factoid-history:" + r.id)) ?? [],
      url = new URL("https://en.wikipedia.org/w/api.php");
    for (const [k, v] of Object.entries({
      action: "query",
      generator: "search",
      gsrsearch: f.Topic,
      gsrlimit: "3",
      prop: "extracts",
      exintro: "1",
      explaintext: "1",
      format: "json",
    }))
      url.searchParams.set(k, v);
    return { state: { index: i }, more: true, record: r, history, url: url.toString() };
  }
  return {
    state: { index: i },
    more: false,
    record: {},
    history: [],
    url: "https://en.wikipedia.org/w/api.php",
  };
}

