export default async function prompt({ record, history, wiki }) {
  const context = Object.values(wiki?.query?.pages ?? {})
    .map((x) => x.extract || "")
    .join("\n")
    .slice(0, 12000);
  return {
    body: {
      model: "llama-3.3-70b-versatile",
      messages: [
        {
          role: "system",
          content:
            "Write one concise accurate fact suitable for a general audience. Use the source context when relevant. Avoid repeating previous facts.",
        },
        {
          role: "user",
          content:
            "Topic: " +
            record.fields.Topic +
            "\nContext: " +
            context +
            "\nPrevious facts: " +
            JSON.stringify(history),
        },
      ],
    },
  };
}

