export default async function imagePrompt({ body, record }, ctx) {
  const fact = body?.choices?.[0]?.message?.content;
  if (typeof fact !== "string" || !fact.trim()) throw Error("Missing generated fact");
  if (!record.id || !record.fields?.Email) throw Error("Subscriber identity missing");
  await ctx.state.set("factoid-pending", {
    stage: "generate illustration",
    id: record.id,
    email: record.fields.Email,
  });
  return {
    fact,
    prompt: "Generate a child-friendly illustration that complements this fact: " + fact,
  };
}

