const esc = (s) =>
  String(s).replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );
export default async function mail({ record, fact, resize, unsubscribeUrl }, ctx) {
  const f = record.fields,
    attachment = resize?.base64;
  if (typeof attachment !== "string" || !attachment) throw Error("Image resize returned no bytes");
  const u = new URL(unsubscribeUrl);
  u.searchParams.set("ID", record.id);
  const body =
    "<p><strong>You asked about " +
    esc(f.Topic) +
    "</strong></p><p><i>" +
    esc(fact) +
    '</i></p><p><a href="' +
    esc(u.toString()) +
    '">Unsubscribe</a></p>';
  await ctx.state.set("factoid-pending", {
    stage: "send fact email",
    id: record.id,
    email: f.Email,
  });
  const sent = await ctx.actions.call("gmail.send_email", {
    to: f.Email,
    subject: "Your " + f.Interval + " factoid",
    body,
    isHtml: true,
    attachments: [{ filename: "factoid.png", mimeType: "image/png", contentBase64: attachment }],
  });
  if (!sent.messageId) throw Error("Email outcome unknown");
  return { messageId: sent.messageId };
}

