export default async function log({ record, messageId }, ctx) {
  if (!messageId) throw Error("Email outcome unknown");
  await ctx.state.set("factoid-pending", {
    stage: "record last sent",
    id: record.id,
    email: record.fields.Email,
  });
  return { records: [{ id: record.id, fields: { "Last Sent": new Date().toISOString() } }] };
}

