export default async function finish({ record, fact, history, records }, ctx) {
  if (records.length !== 1 || records[0].id !== record.id)
    throw Error("Last Sent update unconfirmed");
  await ctx.state.set("factoid-history:" + record.id, [...history, fact].slice(-5));
  await ctx.state.set("factoid-pending", null);
  return { done: true };
}
